const fs=require('fs'),vm=require('vm'),assert=require('node:assert/strict');
const sandbox={TextEncoder};vm.createContext(sandbox);vm.runInContext(fs.readFileSync('static/ui/stock-preparation-group-recovery.js','utf8'),sandbox);const R=sandbox.ERPStockGroupRecovery;
const results=[],selected=process.argv.indexOf('--filter'),filter=selected>=0?new RegExp(process.argv[selected+1]):null;function check(name,fn){if(filter&&!filter.test(name))return;try{fn();results.push({name,passed:true})}catch(error){results.push({name,passed:false,error:error.message})}}
function storage(){const map=new Map();return {map,get length(){return map.size},key:i=>[...map.keys()][i]??null,getItem:k=>map.get(k)??null,setItem:(k,v)=>map.set(k,v),removeItem:k=>map.delete(k)}}
function record(actorId=1,key='group-request-A',groupKey='original-group-A'){return {schema:'stock-group-completion-local-v1',actorId,key,groupKey,parentId:4,endpoint:'/api/production/stock-preparation/group-actions',body:{action:'dispose',operation_key:key,expected_actor_id:actorId,parent_id:4,group_key:groupKey,disposition:'semi',sets:5,jobs:[{job_id:2,actual_output:19},{job_id:1,actual_output:14}]},summary:{code:'组A',jobs:[{jobId:2,output:19},{jobId:1,output:14}]},state:'prepared',hadUnknown:false,createdAt:'2026-10-10'}}
check('写前读回完整原数组顺序，调用方变动不改记录',()=>{const s=storage(),store=R.createStore(s,1),r=record();store.write(r);r.body.jobs.reverse();assert.equal(store.list()[0].body.jobs[0].job_id,2)});
check('新页面同group锁，异group不锁且同parent不同组可存',()=>{const s=storage(),first=R.createStore(s,1);first.write(record());const next=R.createStore(s,1);assert.equal(next.blocked('original-group-A'),true);assert.equal(next.blocked('different-group-B'),false);next.write(record(1,'group-request-B','different-group-B'));assert.equal(next.list().length,2)});
check('同账号双实例不同原key独立保留不覆盖',()=>{const s=storage(),a=R.createStore(s,1),b=R.createStore(s,1);a.write(record());b.write(record(1,'parallel-key'));assert.equal(a.list().length,2)});
check('跨账号读取/移除不碰原账号',()=>{const s=storage(),a=R.createStore(s,1),b=R.createStore(s,2);a.write(record());assert.equal(b.list().length,0);const br=record(2);br.state='confirmed';b.write(br);b.remove(br);assert.equal(a.list().length,1)});
check('同key异body或数组重排拒绝覆盖',()=>{const s=storage(),store=R.createStore(s,1),r=record();store.write(r);r.body.jobs.reverse();assert.throws(()=>store.write(r));assert.equal(store.list()[0].body.jobs[0].job_id,2)});
check('未知不可清或降级为可更正',()=>{const s=storage(),store=R.createStore(s,1),r=record();r.state='unknown';r.hadUnknown=true;store.write(r);assert.throws(()=>store.reject(r));assert.throws(()=>store.remove(r));r.state='prepared';r.hadUnknown=false;assert.throws(()=>store.write(r));assert.equal(store.list().length,1)});
check('写异常与读回异常不能认定可靠保存',()=>{const s=storage(),store=R.createStore(s,1);s.setItem=()=>{throw Error('disk')};assert.throws(()=>store.write(record()));s.setItem=()=>{};assert.throws(()=>store.write(record()))});
check('confirmed清理失败保留且异组不受锁',()=>{const s=storage(),store=R.createStore(s,1),r=record();r.state='confirmed';store.write(r);s.removeItem=()=>{throw Error('remove')};assert.throws(()=>store.remove(r));assert.equal(store.blocked(r.groupKey),true);assert.equal(store.blocked('B'),false)});
check('损坏账号记录或枚举失败不能伪装无记录',()=>{const s=storage(),store=R.createStore(s,1);s.setItem(store.keyFor('broken'),'{}');assert.throws(()=>store.list());s.map.clear();s.key=()=>{throw Error('read')};s.setItem('other','1');assert.throws(()=>store.list())});

